// plugin.ts
function activate(api) {
  const catalogue = api.i18n.register({ ko: KO });
  setTranslator({ t: (text, params) => api.i18n.t(text, params), tc: (context, text, params) => api.i18n.tc(context, text, params) });
  let claims = null;
  const panel = createPanel(api, { afterCommit: () => claims?.refresh() });
  const t2 = api.i18n.t;
  const lookup2 = () => void api.data.load().then(() => {
    const units = api.data.units();
    setGameLookup(units ? lookupOver(units.flingy) : null);
  }, () => setGameLookup(null));
  lookup2();
  const onData = api.events.on("gameData", lookup2);
  api.commands.register({ id: "open", title: "Magenta", enabled: () => api.document.isOpen(), run: (options) => panel.open(options && typeof options === "object" && typeof options.index === "number" ? { index: options.index } : {}) });
  api.commands.register({
    id: "describe",
    title: msg("Magenta: describe a trigger"),
    run: (trigger4) => {
      const tr = trigger4;
      const host = new Host(api);
      const namer = host.namer(host.sidecar());
      const extra = host.extra();
      return {
        conditions: liveConditions(tr).map((c2) => conditionText(c2, namer, extra)),
        actions: actionsText(liveActions(tr), namer, extra).map((s) => s.text)
      };
    }
  });
  registerPreferencesPage(api, () => panel.relayout());
  api.commands.register({ id: "settings", title: msg("Magenta Settings"), run: () => openSettings(api) });
  api.menu.add("Triggers", { label: msg("Magenta\u2026"), shortcut: "Ctrl+Shift+M", icon: "plugin", after: "Text Trigger Editor\u2026", enabled: () => api.document.isOpen(), command: "open" });
  api.hotkeys.add("Ctrl+Shift+M", { command: "open" });
  claims = installClaims(api, (index) => panel.open({ index }));
  const under = (ctx) => {
    const point = ctx.point ?? (ctx.tile ? { px: ctx.tile.x * 32 + 16, py: ctx.tile.y * 32 + 16 } : null);
    if (!point) return {};
    const host = new Host(api);
    const scn = api.document.scenario();
    const names = api.triggers.names();
    const dat = api.data.units();
    let unit = null;
    let best = Infinity;
    for (const u of host.placedUnits()) {
      const hw = dat && u.unitId < dat.placementWidth.length ? Math.max(16, dat.placementWidth[u.unitId] / 2) : 16;
      const hh = dat && u.unitId < dat.placementHeight.length ? Math.max(16, dat.placementHeight[u.unitId] / 2) : 16;
      if (Math.abs(u.x - point.px) > hw || Math.abs(u.y - point.py) > hh) continue;
      const d = (u.x - point.px) ** 2 + (u.y - point.py) ** 2;
      if (d < best) {
        best = d;
        unit = { unitId: u.unitId, owner: u.owner, slot: u.slot, name: names.unit(u.unitId), ownerName: api.names.playerGroup(u.owner) };
      }
    }
    let location = null;
    let area = Infinity;
    scn?.locations.forEach((l, i) => {
      if (i === 63) return;
      const x0 = Math.min(l.left, l.right), x1 = Math.max(l.left, l.right), y0 = Math.min(l.top, l.bottom), y1 = Math.max(l.top, l.bottom);
      if (x0 === x1 || y0 === y1 || point.px < x0 || point.px >= x1 || point.py < y0 || point.py >= y1) return;
      const a2 = (x1 - x0) * (y1 - y0);
      if (a2 < area) {
        area = a2;
        location = { number: i + 1, name: names.location(i + 1) };
      }
    });
    return { unit, location };
  };
  const unitItem = api.contextMenu.add("viewport", {
    label: (ctx) => t2("New trigger about this {unit}\u2026", { unit: under(ctx).unit?.name ?? "" }),
    visible: (ctx) => api.document.isOpen() && !!under(ctx).unit,
    run: (ctx) => {
      const s = under(ctx);
      panel.start(starters({ unit: s.unit, location: s.location }));
    }
  });
  const locationItem = api.contextMenu.add("viewport", {
    label: (ctx) => t2("New trigger at {location}\u2026", { location: under(ctx).location?.name ?? "" }),
    visible: (ctx) => api.document.isOpen() && !!under(ctx).location,
    run: (ctx) => {
      const s = under(ctx);
      panel.start(starters({ location: s.location }));
    }
  });
  return () => {
    claims?.dispose();
    panel.close();
    onData.dispose();
    unitItem.dispose();
    locationItem.dispose();
    setGameLookup(null);
    setTranslator(null);
    catalogue.dispose();
  };
}
export {
  activate
};
